float rand1d(float x) {
    return fract(sin(x) * 43123.1233);
}

float rand2d(vec2 st) {
    return rand1d(dot(st, vec2(12.24523, 78.233)));
}



// 2D Noise based on Morgan McGuire @morgan3d
// https://www.shadertoy.com/view/4dS3Wd
float noise(in vec2 st) {
    vec2 i = floor(st);
    vec2 f = fract(st);

    // Four corners in 2D of a tile
    float a = rand2d(i);
    float b = rand2d(i + vec2(1.0, 0.0));
    float c = rand2d(i + vec2(0.0, 1.0));
    float d = rand2d(i + vec2(1.0, 1.0));

    // Smooth Interpolation

    // Cubic Hermine Curve.  Same as SmoothStep()
    vec2 u = f*f*(3.0-2.0*f);
    // u = smoothstep(0.,1.,f);

    // Mix 4 coorners percentages
    return mix(a, b, u.x) +
            (c - a)* u.y * (1.0 - u.x) +
            (d - b) * u.x * u.y;
}



// https://iquilezles.org/articles/distfunctions2d/
float sdEgg( in vec2 p, in float ra, in float rb )
{
    const float k = sqrt(3.0);
    p.x = abs(p.x);
    float r = ra - rb;
    return ((p.y<0.0)       ? length(vec2(p.x,  p.y    )) - r :
            (k*(p.x+r)<p.y) ? length(vec2(p.x,  p.y-k*r)) :
                              length(vec2(p.x+r,p.y    )) - 2.0*r) - rb;
}

const vec3 BLACK = vec3(0.0);
const vec3 YELLOW = vec3(1.0, 0.729, 0.031);
const vec3 ORANGE = vec3(0.91, 0.365, 0.016);
const vec3 GLOW = vec3(1.0, 0.729, 0.3);
const float FRAC_PI_2 = 1.57079632679;


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Pixelate
    float psize = min(iResolution.x, iResolution.y) / 20.0;
    vec2 pixel = floor(fragCoord / psize) * psize;

    // y-range: -1.0 to 1.0
    // x-range: -2.0 to 2.0 (not tight)
    vec2 p = (2.0*fragCoord-iResolution.xy) / iResolution.y;

    // For the noise texture, but it really doesn't matter and
    // I was too lazy to delete.
    vec2 uv = fragCoord / iResolution.xy;

    // Time varying pixel color
    float dist = sdEgg(p * 1.5, 0.7, 0.3);
    // FIXME: This should be smooth noise, otherwise we get the
    // choppiness.
    float offset = noise(p + iTime);
    dist += offset * 0.2;
    dist = abs(min(dist, 0.0));

    // Radial gradient to fake some lighting
    float grad = min(1.0 - length(p * 0.5), 1.0);
    vec3 background = mix(BLACK, GLOW, grad + offset * 0.15);

    float thresh = smoothstep(0.4,.8, dist);
    vec3 col = mix(ORANGE, YELLOW , smoothstep(0.05, 0.7,dist));
    col = mix(background, col, smoothstep(0.02, 0.2, dist));

    // Output to screen
    fragColor = vec4(vec3(grad), 1.0);
    fragColor = vec4(col, 1.0);
}
